def preparar(apps, schema_editor):
    """La fila de la cadena, y la auditoría para la alcaldía (en una base nueva ya viene por defecto)."""
    apps.get_model('Auditoria', 'CadenaAuditoria').objects.get_or_create(pk=1)
    Roles = apps.get_model('Users', 'Roles')
    for rol in Roles.objects.filter(name__in=['Alcalde', 'Vicealcalde']):
        permisos = dict(rol.permisos or {})
        if 'auditoria.ver' not in permisos:
            permisos['auditoria.ver'] = 'todos'
            rol.permisos = permisos
            rol.save(update_fields=['permisos'])


